    <form onSubmit={submit} style={{ display: 'grid', gap: '16px', maxWidth: '420px' }}>
      <JxInputField
        label="Имя"
        required
        placeholder="Как вас зовут"
        value={name}
        onChange={(event) => setName(event.target.value)}
        errorText={nameError}
      />

      <JxSelect
        label="Язык интерфейса"
        placeholder="Выберите язык"
        options={LANGUAGE_OPTIONS}
